"  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const [passcodeModal, setPasscodeModal] = useState({
    isOpen: false,
    actionKey: '',
    actionName: '',
    onSuccess: null
  });

  const getPermissionValue = (section, perm) => {
    const access = getStaffPermissions()?.pos_access;
    if (!access) return true;
    const parts = section.split('.');
    let current = access;
    for (const part of parts) {
      if (current) {
        current = current[part];
      }
    }
    if (!current) return true;
    return current[perm];
  };

  const isFeatureVisible = (section, perm) => {
    const directVal = getPermissionValue(section, perm);
    const passcodeVal = getPermissionValue(section, `${perm}_passcode`);
    return directVal !== false || passcodeVal === true;
  };

  const checkPermissionAndExecute = (section, perm, actionName, onExecute) => {
    const directVal = getPermissionValue(section, perm);
    const passcodeVal = getPermissionValue(section, `${perm}_passcode`);

    if (directVal !== false && passcodeVal !== true) {
      onExecute();
    } else {
      setPasscodeModal({
        isOpen: true,
        actionKey: perm,
        actionName: actionName,
        onSuccess: onExecute
      });
    }
  };

  const getBillingPermissionSection = () => {
    if (orderType === 'QUICK') return 'QuickBill';
    if (orderType === 'DELIVERY') return 'Delivery.Billing';
    if (orderType === 'PICKUP') return 'Pickup.Billing';
    if (orderType === 'PRE_ORDER') return 'PreOrder.Billing';
    return 'Billing';
  };

  const getOldKOTPermissionSection = () => {
    if (orderType === 'DELIVERY') return 'Delivery.OldKOT';
    if (orderType === 'PICKUP') return 'Pickup.OldKOT';
    if (orderType === 'PRE_ORDER') return 'PreOrder.OldKOT';
    return 'OldKOT';
  };

  const [showPassword, setShowPassword] = useState(false);"
